k-anonymity.pseudocode:
def is_k_anonymous(rows, qi, k):
    groups = {}
    for r in rows:
        key = tuple(r[a] for a in qi)  # 준식별자 조합
        groups[key] = groups.get(key, 0) + 1
    return min(groups.values()) >= k  # 최소 클래스 크기

def is_l_diverse(rows, qi, sensitive, l):  # 보완 모델
    groups = {}
    for r in rows:
        key = tuple(r[a] for a in qi)
        groups.setdefault(key, set()).add(r[sensitive])
    return all(len(v) >= l for v in groups.values())

k-nearest-neighbor.pseudocode:
def knn_predict(train, x, k, mode='class'):
    # train: [(특징 벡터, 레이블 또는 값), ...]
    dists = []
    for feat, y in train:
        d = sum((a - b) ** 2 for a, b in zip(feat, x))
        dists.append((d ** 0.5, y))  # 유클리드 거리
    dists.sort(key=lambda t: t[0])  # 가까운 순
    top = dists[:k]
    if mode == 'class':  # 다수결
        votes = {}
        for _, y in top:
            votes[y] = votes.get(y, 0) + 1
        return max(votes, key=votes.get)
    if mode == 'wknn':  # 거리 역수 가중 평균
        w = [1 / (d + 1e-9) for d, _ in top]
        num = sum(wi * y for wi, (_, y) in zip(w, top))
        return num / sum(w)
    return sum(y for _, y in top) / k  # 회귀: 평균

k-nearest-neighbors.pseudocode:
# train: [(특징 벡터, 레이블)], 스케일링 완료 가정
def knn_predict(train, x, k, task='classify'):
    dists = sorted((dist(x, xi), yi) for xi, yi in train)
    neighbors = [y for _, y in dists[:k]]  # 최근접 k개
    if task == 'classify':
        votes = {}
        for y in neighbors:  # 다수결 투표
            votes[y] = votes.get(y, 0) + 1
        return max(votes, key=votes.get)
    return sum(neighbors) / k  # 회귀: 평균
